-- WoW Forever: The Drowned City (map 2970) repopulated from live data. Fox (RU) found the dungeon nearly empty. Our
-- 2026_11_11_30 had no live data: 137 spawns on guessed spots, 9 kinds of mob that live does not have in the city, and the bosses
-- far from where live players kill them (Var'Taka 470 y off, Min'loth 145 y).
-- Source: the EG Link combat logs (Efficient Games, CC BY 4.0, https://efficient.games), client builds 70938 and 70959, three
-- runs: the creatures players fought in map 2970, where each one died, its level, health and the spells it cast, and where each
-- boss encounter was pulled. What is real and what is ours:
--  * real: which creatures stand in the city (29 kinds and the critters), how many of each one run has (the logs' spawn counts),
--    levels, health multipliers, models, classes and the spells they use; the spot of every live kill (x, y), the boss pull spots.
--  * ours: the height of each spot (the floor of the 2970 navmesh under the live x, y; in the flooded quarter, where the mesh has
--    a sea floor and a water surface, the one the neighbouring spots stand on: INFERRED, every such row says so), spots for mobs
--    a run has more of than the logs have kill spots (pack mates 3-6 y away, INFERRED), facing, spell timers (INFERRED), gold.
-- Deathless Watchers, Guardians and Sorcerers 260205/260213/260214 fight in every run but never die: Deathless Marrow raises
-- them, they are not spawns (classic_instance_the_drowned_city.cpp). The Unstable Crystals 268374 are left out: never killed,
-- no spells, nothing says what they do. Zin'aka (rare, in no log) keeps the spot 2026_11_11_30 gave him.
-- A kill spot is where the mob died, so a pack may stand a few yards from where live keeps it.
-- Spawn guids 48100000-48100299 (the old range, emptied first). Safe to run again.

-- new templates from players' caches (faction 16 INFERRED; critters 188)
DELETE FROM `creature_template` WHERE `entry` IN (258849,268300,268321,268462,263055,263061,263064);
DELETE FROM `creature_template_difficulty` WHERE `Entry` IN (258849,268300,268321,268462,263055,263061,263064);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (258849,268300,268321,268462,263055,263061,263064);
UPDATE `creature_template` SET `unit_flags2` = 0 WHERE `entry` IN (263055,263061,263064);

-- Marrow's raised dead at the live health multipliers
UPDATE `creature_template_difficulty` SET `HealthModifier` = 1.5 WHERE `Entry` = 260205 AND `DifficultyID` = 0;
UPDATE `creature_template_difficulty` SET `HealthModifier` = 1.8 WHERE `Entry` = 260213 AND `DifficultyID` = 0;
UPDATE `creature_template_difficulty` SET `HealthModifier` = 1.5 WHERE `Entry` = 260214 AND `DifficultyID` = 0;

-- levels as live players met them (the combat logs), bosses included
DELETE FROM `creature_classic_level` WHERE `entry` IN (250187,258792,258797,258799,258804,258818,258849,258897,259979,259981,259987,260096,260353,263196,263229,263899,268300,268321,268462,268476,268477,268478,264177,263055,263061,263064,258905,258924,260042,260202,263886,260243,260205,260213,260214);

-- the I'lalai Fetish also drops from the Undying Offerings (players' caches; chance INFERRED like the others in 2026_11_11_30)
UPDATE `creature_template_difficulty` SET `LootID` = `Entry` WHERE `Entry` = 263899 AND `DifficultyID` = 0;
DELETE FROM `creature_loot_template` WHERE `Entry` = 263899 AND `Item` = 270343;

-- what the mobs cast: the spells each one cast in the combat logs (timers INFERRED). This replaces 2026_11_11_30's guesses.
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (250187,258792,258794,258797,258799,258804,258818,258849,258897,259979,259981,259987,260096,260205,260213,260214,260353,263196,263229,263899,264177,268300,268321,268462,268476,268477,268478,268515,268516,268517);
UPDATE `creature_template` SET `AIName` = 'SmartAI', `ScriptName` = '' WHERE `entry` IN (250187,258792,258797,258799,258804,258818,258849,258897,259979,259981,259987,260096,260205,260213,260214,260353,263196,264177,268321,268462,268476,268477,268478);
UPDATE `creature_template` SET `AIName` = '' WHERE `entry` IN (263229,263899,268300);

-- spawns: every live kill spot (x, y from the logs, the height from the navmesh), the bosses where live kills them
DELETE FROM `creature` WHERE `guid` BETWEEN 48100000 AND 48100299;
